// Package system assembles scaffolded integrations into a system host. It
// scans the workspace for the .intropy/scaffold.json records `int create`
// left behind, renders the system-host template with the template
// package's machinery, and generates the typed system declaration —
// Topics.cs and the ISystemDefinition class — from what the scaffolds
// recorded.
package system

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/huandu/xstrings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// hostTemplate is the directory in the templates repo holding the system
// host's shell and placeholders.
const hostTemplate = "system-host"

type CreateOptions struct {
	Name       string // system name as typed; PascalCase or kebab-case
	StartDir   string // workspace scan root; default "."
	OutputDir  string // default: the kebab-cased name
	Version    string // template release tag; default: latest
	Force      bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Owner and Repo select the template library; zero values target the
	// official library. GitHubBaseURL is a test-only seam.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// CreateResult is the machine-readable summary written when --output-json
// is set. Field names are stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`
	System    Summary        `json:"system"`
}

// Summary describes the assembled system; it loosely mirrors the model the
// host's `graph` verb prints.
type Summary struct {
	Name          string      `json:"name"`
	Components    []Component `json:"components"`
	Topics        []Topic     `json:"topics"`
	Connectors    []Connector `json:"connectors,omitempty"`
	SharedLibrary string      `json:"sharedLibrary"` // scaffold directory
}

func (o *CreateOptions) applyDefaults() {
	if o.StartDir == "" {
		o.StartDir = "."
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Create runs the full assembly: scan the workspace for scaffold records,
// validate them into a system model, render the system-host template, and
// generate the declaration files from the model. All local validation
// happens before any network I/O.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if opts.Name == "" {
		return fmt.Errorf("a system name is required")
	}

	// Exact parity with the templates' `{{ .name | kebabcase }}`: sprig
	// delegates to xstrings, so OrderFlow and order-flow are equivalent.
	kebab := xstrings.ToKebabCase(opts.Name)
	if opts.OutputDir == "" {
		opts.OutputDir = kebab
	}

	entries, warnings := template.ListScaffolds(opts.StartDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}
	warnf := func(format string, args ...any) {
		fmt.Fprintf(opts.Stderr, "warning: "+format+"\n", args...)
	}
	model, err := Assemble(entries, warnf)
	if err != nil {
		return err
	}
	model.Name = kebab

	include, err := contractsInclude(opts.OutputDir, model.Shared)
	if err != nil {
		return err
	}

	if err := template.Create(ctx, template.CreateOptions{
		Template:      hostTemplate,
		OutputDir:     opts.OutputDir,
		Version:       opts.Version,
		SetValues:     map[string]any{"name": kebab},
		Force:         opts.Force,
		NoInput:       true, // the template's contract: only `name`, never prompt
		Stdin:         strings.NewReader(""),
		Stdout:        opts.Stdout,
		Stderr:        opts.Stderr,
		HTTP:          opts.HTTP,
		UserAgent:     opts.UserAgent,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		GitHubBaseURL: opts.GitHubBaseURL,
	}); err != nil {
		return err
	}

	// The template derives projectName/systemClass from the name; reading
	// them back from the record it just wrote makes CLI/template
	// derivation drift impossible.
	record, err := template.LoadScaffold(filepath.Join(opts.OutputDir, filepath.FromSlash(template.ScaffoldRelPath)))
	if err != nil {
		return err
	}
	hostEntry := template.ScaffoldEntry{Path: opts.OutputDir, Scaffold: *record}
	if model.ProjectName, err = stringValue(hostEntry, "projectName"); err != nil {
		return fmt.Errorf("template %s did not derive the host project name: %w", hostTemplate, err)
	}
	if model.SystemClass, err = stringValue(hostEntry, "systemClass"); err != nil {
		return fmt.Errorf("template %s did not derive the system class name: %w", hostTemplate, err)
	}

	if err := writeTopicsFile(opts.OutputDir, model); err != nil {
		return err
	}
	withDevelopment, err := writeDevelopmentFile(opts.OutputDir, model, warnf)
	if err != nil {
		return err
	}
	withConnectors, err := writeConnectorsFile(opts.OutputDir, model, withDevelopment, warnf)
	if err != nil {
		return err
	}
	if err := writeSystemClassFile(opts.OutputDir, model, withConnectors, withDevelopment); err != nil {
		return err
	}
	if withConnectors {
		// The drop folders behind the connectors' local resolutions, so an
		// extractor's first poll doesn't hit a missing directory.
		for _, c := range model.Connectors {
			if err := os.MkdirAll(filepath.Join(opts.OutputDir, "test", c.Name), 0o755); err != nil {
				return fmt.Errorf("create connector test folder: %w", err)
			}
		}
	}
	csproj := filepath.Join(opts.OutputDir, model.ProjectName+".SystemHost.csproj")
	if err := insertProjectReference(csproj, include); err != nil {
		return err
	}

	fmt.Fprintf(opts.Stderr, "assembled system %q: %d component(s), %d topic(s), %d connector(s), contracts from %s\n",
		model.Name, len(model.Components), len(model.Topics), len(model.Connectors), model.Shared.Path)

	return maybeWriteCreateResult(opts, record, model)
}

func maybeWriteCreateResult(opts CreateOptions, record *template.Scaffold, model *Model) error {
	if opts.OutputJSON == "" {
		return nil
	}
	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:  hostTemplate,
		Owner:     record.Owner,
		Repo:      record.Repo,
		Version:   record.Version,
		OutputDir: absOut,
		Values:    record.Values,
		System: Summary{
			Name:          model.Name,
			Components:    model.Components,
			Topics:        model.Topics,
			Connectors:    model.Connectors,
			SharedLibrary: model.Shared.Path,
		},
	}
	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	data = append(data, '\n')
	if opts.OutputJSON == "-" {
		if _, err := opts.Stdout.Write(data); err != nil {
			return fmt.Errorf("write --output-json: %w", err)
		}
		return nil
	}
	if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

package system

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"text/template"

	intropytemplate "github.com/integrio-intropy/intropy-cli/internal/template"
)

// The generated declaration files. Deliberately namespace-less: the host
// project is small enough that the declaration reads as one document, and
// discovery reflects over the assembly regardless.
const topicsFileTmpl = `using Intropy.Topology;
using {{ .Shared.Name }};

/// <summary>The system's topics, each defined once and shared by every component that touches it.</summary>
public static class Topics
{
{{- range $i, $t := .Topics }}
{{- if $i }}
{{ end }}
    /// <summary>{{ $t.Contract }} messages on topic '{{ $t.Name }}' (pubsub '{{ $t.Pubsub }}').</summary>
    public static readonly TopicRef<{{ $t.Contract }}> {{ $t.Field }} = TopicRef<{{ $t.Contract }}>.Define("{{ $t.Pubsub }}", "{{ $t.Name }}");
{{- end }}
}
`

const connectorsFileTmpl = `using Intropy.Topology;

/// <summary>The system's connectors: the named ports its edge blocks reach the outside world through. Each declares its deployed transport; the development definition resolves it to a local folder under test/ so the system runs with zero external configuration.</summary>
public static class Connectors
{
{{- range $i, $c := .Connectors }}
{{- if $i }}
{{ end }}
    /// <summary>Placeholder transport — replace with a concrete transport (e.g. <c>Transport.Sftp()</c>) before deployment. Locally resolved to <c>./test/{{ $c.Name }}</c>.</summary>
    public static readonly ConnectorRef {{ $c.Field }} = ConnectorRef.Define("{{ $c.Name }}", Transport.Default());
{{- end }}
}
`

// connectorsFileLegacyTmpl is the pre-development shape: a template release
// without the Development.cs placeholder pins an Intropy.Topology whose
// connectors carry a local file transport directly.
const connectorsFileLegacyTmpl = `using Intropy.Topology;

/// <summary>The system's connectors: the named ports its edge blocks reach the outside world through. Each defaults to a local file folder under test/ so the system runs with zero external configuration.</summary>
public static class Connectors
{
{{- range $i, $c := .Connectors }}
{{- if $i }}
{{ end }}
    /// <summary>Local file connector '{{ $c.Name }}' (folder ./test/{{ $c.Name }}). Point it at a real external system and transport when known.</summary>
    public static readonly ConnectorRef {{ $c.Field }} = ConnectorRef.Define("{{ $c.Name }}", Transport.File("./test/{{ $c.Name }}"));
{{- end }}
}
`

// The mock artifacts are static skeleton files, shipped by the same template
// release that ships the Development.cs placeholder — the paths never vary.
const developmentFileTmpl = `using Intropy.Topology.Generation;

/// <summary>Local OpenAPI-backed substitutes and connector file resolutions for {{ .Name }}.</summary>
public sealed class {{ .ProjectName }}Development : IDevelopmentDefinition
{
    /// <inheritdoc />
    public void Define(DevelopmentBuilder development)
    {
        development.Mock(Services.Idempotency).FromOpenApi("mocks/idempotency-service.openapi.yaml");
        development.Mock(Services.BusinessIncidents).FromOpenApi("mocks/business-incident-service.openapi.yaml");
{{- range .Connectors }}
        development.Files(Connectors.{{ .Field }}).RootPath("./test/{{ .Name }}");
{{- end }}
    }
}
`

const systemClassFileTmpl = `using Intropy.Topology;

/// <summary>The {{ .Name }} system: what exists, and what connects it.</summary>
public sealed class {{ .SystemClass }} : ISystemDefinition
{
    public string SystemName => "{{ .Name }}";

    public void Define(SystemBuilder builder)
    {
{{- range .Components }}
        builder.{{ .Add }}("{{ .AppID }}")
{{- range .Calls }}
            {{ . }}
{{- end }};
{{- end }}
    }
}
`

// defaultExtractorSchedule is the cron every generated extractor starts with:
// once every minute. Extractors are run-to-completion jobs, so the host re-runs
// them on this schedule (CronJob emulation locally, a real CronJob in
// production). The generated file is the user's after `sys create` — edit the
// cron in place.
const defaultExtractorSchedule = "* * * * *"

var (
	topicsFile           = template.Must(template.New("Topics.cs").Parse(topicsFileTmpl))
	connectorsFile       = template.Must(template.New("Connectors.cs").Parse(connectorsFileTmpl))
	connectorsFileLegacy = template.Must(template.New("Connectors.cs").Parse(connectorsFileLegacyTmpl))
	developmentFile      = template.Must(template.New("Development.cs").Parse(developmentFileTmpl))
	systemClassFile      = template.Must(template.New("SystemClass.cs").Parse(systemClassFileTmpl))
)

// componentView is a Component with its builder call and chained wiring calls
// resolved for the system class template. Each call renders on its own line.
type componentView struct {
	AppID string
	Add   string   // AddExtractor | AddLoader
	Calls []string // the chained calls in order, e.g. `.From(...)`, `.Publishes(...)`, `.WithSchedule(...)`
}

// writeTopicsFile overwrites <dir>/Topics.cs with the assembled topic
// declarations.
func writeTopicsFile(dir string, m *Model) error {
	return renderTo(filepath.Join(dir, "Topics.cs"), topicsFile, m)
}

// writeDevelopmentFile overwrites <dir>/<ProjectName>Development.cs with the
// assembled development definition: the platform-service mocks plus one file
// resolution per connector. Like the system class it refuses to create the
// file — a missing placeholder means the template release predates
// development definitions (and its pinned Intropy.Topology has no
// IDevelopmentDefinition), so it reports false and the caller degrades the
// connector and system-class shapes to that era instead of failing.
func writeDevelopmentFile(dir string, m *Model, warnf func(format string, args ...any)) (bool, error) {
	path := filepath.Join(dir, m.ProjectName+"Development.cs")
	if _, err := os.Stat(path); err != nil {
		warnf("template rendered no %sDevelopment.cs placeholder — this release predates development definitions; generating connectors with local file transports (upgrade with --version <newer tag> for deployed transports and local service mocks)", m.ProjectName)
		return false, nil
	}
	return true, renderTo(path, developmentFile, m)
}

// writeConnectorsFile overwrites <dir>/Connectors.cs with the assembled
// connector declarations. Like the system class it refuses to create the
// file — but here a missing placeholder means the template release predates
// connectors entirely, so the system is generated without From/To instead of
// failing: it reports false and the caller degrades the system class the
// same way. withDevelopment=false (a release with connectors but no
// development definitions) keeps the era's local file transports; otherwise
// connectors declare their deployed transport shape and the development
// definition owns the local resolution.
func writeConnectorsFile(dir string, m *Model, withDevelopment bool, warnf func(format string, args ...any)) (bool, error) {
	path := filepath.Join(dir, "Connectors.cs")
	if _, err := os.Stat(path); err != nil {
		warnf("template rendered no Connectors.cs placeholder — this release predates connectors; generating the system without From/To (upgrade with --version <newer tag> to wire them)")
		return false, nil
	}
	tmpl := connectorsFile
	if !withDevelopment {
		tmpl = connectorsFileLegacy
	}
	return true, renderTo(path, tmpl, m)
}

// writeSystemClassFile overwrites <dir>/<SystemClass>.cs with the assembled
// system definition. It refuses to create the file: the rendered template
// must have left the placeholder, or its name derivation disagrees with
// this CLI and the write would add a second ISystemDefinition instead of
// replacing the placeholder. withConnectors=false (a template release that
// predates Connectors.cs) omits the From/To calls; withDevelopment=false
// (a release that predates development definitions, whose skeleton ships no
// Services.cs) omits the Uses calls.
func writeSystemClassFile(dir string, m *Model, withConnectors, withDevelopment bool) error {
	path := filepath.Join(dir, m.SystemClass+".cs")
	if _, err := os.Stat(path); err != nil {
		return fmt.Errorf("template rendered no %s.cs placeholder: the template's systemClass derivation disagrees with this CLI; upgrade intropy or pass --version <compatible tag>", m.SystemClass)
	}

	views := make([]componentView, len(m.Components))
	fieldByKey := map[TopicKey]string{}
	for _, t := range m.Topics {
		fieldByKey[t.TopicKey] = t.Field
	}
	connectorField := map[string]string{}
	for _, c := range m.Connectors {
		connectorField[c.Name] = c.Field
	}
	for i, c := range m.Components {
		v := componentView{AppID: c.AppID}
		topicField := fieldByKey[c.Topic]
		field, hasConnector := connectorField[c.Connector]
		hasConnector = hasConnector && withConnectors
		if c.Kind == intropytemplate.BlockKindExtractor {
			v.Add = "AddExtractor"
			if hasConnector {
				v.Calls = append(v.Calls, ".From(Connectors."+field+")")
			}
			v.Calls = append(v.Calls, ".Publishes(Topics."+topicField+")")
			v.Calls = append(v.Calls, usesCalls(withDevelopment)...)
			// Gated on the same signal as From/To: a template release that
			// predates Connectors.cs also pins an Intropy.Topology without
			// WithSchedule, so the degraded shape must not call it.
			if withConnectors {
				v.Calls = append(v.Calls, `.WithSchedule("`+defaultExtractorSchedule+`")`)
			}
		} else {
			v.Add = "AddLoader"
			v.Calls = append(v.Calls, ".Subscribes(Topics."+topicField+")")
			if hasConnector {
				v.Calls = append(v.Calls, ".To(Connectors."+field+")")
			}
			v.Calls = append(v.Calls, usesCalls(withDevelopment)...)
		}
		views[i] = v
	}

	return renderTo(path, systemClassFile, struct {
		Name        string
		SystemClass string
		Components  []componentView
	}{m.Name, m.SystemClass, views})
}

// usesCalls is the platform-service wiring every block gets: the framework's
// block builders require idempotency and business-incident routing, and the
// skeleton's Services.cs declares both refs. Gated on the development era —
// earlier skeletons ship no Services.cs and pin an Intropy.Topology without
// Uses.
func usesCalls(withDevelopment bool) []string {
	if !withDevelopment {
		return nil
	}
	return []string{".Uses(Services.Idempotency)", ".Uses(Services.BusinessIncidents)"}
}

func renderTo(path string, tmpl *template.Template, data any) error {
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, data); err != nil {
		return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
	}
	if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
		return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
	}
	return nil
}

package system

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// insertProjectReference inserts an ItemGroup referencing the shared
// contracts project immediately before the closing </Project> tag. The
// csproj was rendered by this run seconds earlier, so its shape is known;
// textual insertion preserves the template's comments and formatting,
// which encoding/xml round-tripping would destroy. include is
// slash-separated and relative to the csproj's directory.
func insertProjectReference(csprojPath, include string) error {
	data, err := os.ReadFile(csprojPath)
	if err != nil {
		return fmt.Errorf("reference shared contracts project: %w", err)
	}
	content := string(data)
	idx := strings.LastIndex(content, "</Project>")
	if idx < 0 {
		return fmt.Errorf("reference shared contracts project: rendered %s has no </Project> closing tag", filepath.Base(csprojPath))
	}

	// IsAspireProjectResource="false" keeps the Aspire AppHost from
	// treating the class library as an orchestrated resource.
	itemGroup := "    <ItemGroup>\n" +
		"        <!-- Shared contracts project, referenced by `intropy sys create`. -->\n" +
		"        <ProjectReference Include=\"" + include + "\" IsAspireProjectResource=\"false\" />\n" +
		"    </ItemGroup>\n\n"

	updated := content[:idx] + itemGroup + content[idx:]
	if err := os.WriteFile(csprojPath, []byte(updated), 0o644); err != nil {
		return fmt.Errorf("reference shared contracts project: %w", err)
	}
	return nil
}

// contractsInclude computes the ProjectReference Include path from the
// host's output directory to the shared library's csproj, slash-separated.
func contractsInclude(outputDir string, shared SharedLibrary) (string, error) {
	absOut, err := filepath.Abs(outputDir)
	if err != nil {
		return "", err
	}
	absShared, err := filepath.Abs(shared.Path)
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(absOut, absShared)
	if err != nil {
		return "", fmt.Errorf("compute path from %s to shared contracts project %s: %w", outputDir, shared.Path, err)
	}
	return filepath.ToSlash(filepath.Join(rel, shared.Name+".csproj")), nil
}

package system

import (
	"errors"
	"fmt"
	"path/filepath"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// ErrNoComponents is returned when the workspace scan finds no scaffold
// record `sys create` can assemble into a component.
var ErrNoComponents = errors.New("no assemblable integration scaffolds found")

// Assemble classifies workspace scaffold records into a system model:
// shared-library records become the referenced contract project,
// extractor/loader records become components, and everything else is
// skipped through warnf. The returned model's Name/ProjectName/SystemClass
// are left empty — the caller fills them around the template render.
func Assemble(entries []template.ScaffoldEntry, warnf func(format string, args ...any)) (*Model, error) {
	var (
		components  []Component
		shared      []SharedLibrary
		byAppID     = map[string]string{}   // appId -> scaffold dir
		byTopic     = map[TopicKey]Topic{}  // key -> first-seen topic
		firstDir    = map[TopicKey]string{} // key -> dir that defined it
		byConnector = map[string]string{}   // connector -> scaffold dir
	)

	for _, e := range entries {
		switch {
		case e.Role == template.RoleSharedLibrary:
			name, err := stringValue(e, "name")
			if err != nil {
				return nil, err
			}
			shared = append(shared, SharedLibrary{Path: e.Path, Name: name})
			continue
		case e.Role == template.RoleSystemHost:
			warnf("skipping %s: an existing system host", e.Path)
			continue
		case e.BlockKind == "":
			warnf("skipping %s: scaffold record has no block kind — re-scaffold with a newer template release to include it", e.Path)
			continue
		case e.BlockKind != template.BlockKindExtractor && e.BlockKind != template.BlockKindLoader:
			warnf("skipping %s: unsupported block kind %q (sys create assembles extractors and loaders only)", e.Path, e.BlockKind)
			continue
		}

		appID, err := stringValue(e, "appId")
		if err != nil {
			return nil, err
		}
		topic, err := stringValue(e, "topic")
		if err != nil {
			return nil, err
		}
		contract, err := stringValue(e, "contract")
		if err != nil {
			return nil, fmt.Errorf("%w\nRe-scaffold this integration with a template release that records the contract type, or add \"contract\": \"<TypeName>\" to the record's values.", err)
		}
		pubsub, err := stringValueDefault(e, "pubsub", "pubsub")
		if err != nil {
			return nil, err
		}
		// No CLI-side fallback for the connector: a default would describe a
		// binding the rendered code doesn't use. A component without one is
		// valid topology — it just gets no From/To.
		connector := ""
		if _, ok := e.Values["connector"]; ok {
			if connector, err = stringValue(e, "connector"); err != nil {
				return nil, err
			}
		} else {
			warnf("%s: scaffold record has no connector — re-scaffold with a newer template release to wire From/To", e.Path)
		}

		if prev, ok := byAppID[appID]; ok {
			return nil, fmt.Errorf("duplicate component name %q: declared by both %s and %s (component names must be unique in a system)", appID, prev, e.Path)
		}
		byAppID[appID] = e.Path

		if connector != "" {
			if prev, ok := byConnector[connector]; ok {
				return nil, fmt.Errorf("duplicate connector %q: declared by both %s and %s (each edge block gets its own port; rename one in the record's values)", connector, prev, e.Path)
			}
			byConnector[connector] = e.Path
		}

		key := TopicKey{Pubsub: pubsub, Name: topic}
		if seen, ok := byTopic[key]; ok {
			if seen.Contract != contract {
				return nil, fmt.Errorf("topic %q on pubsub %q has conflicting contracts: %q (%s) vs %q (%s)", topic, pubsub, seen.Contract, firstDir[key], contract, e.Path)
			}
		} else {
			byTopic[key] = Topic{TopicKey: key, Contract: contract, Field: pascalIdent(topic)}
			firstDir[key] = e.Path
		}

		components = append(components, Component{AppID: appID, Kind: e.BlockKind, Topic: key, Connector: connector, Path: e.Path})
	}

	if len(components) == 0 {
		return nil, fmt.Errorf("%w in this directory\nScaffold extractors and loaders first ('intropy int create extractor -n <Name> -s topic=<topic> ...'), then run 'intropy sys create' from the workspace root.", ErrNoComponents)
	}
	switch {
	case len(shared) == 0:
		return nil, fmt.Errorf("no shared contracts project found (template role %q): Topics.cs needs the contract types\nComponents scaffolded from the official extractor/loader templates create a sibling Contracts/ project automatically.", template.RoleSharedLibrary)
	case len(shared) > 1:
		dirs := make([]string, len(shared))
		for i, s := range shared {
			dirs[i] = s.Path
		}
		return nil, fmt.Errorf("found %d shared contract projects (%s); a system host references exactly one — remove or consolidate before re-running", len(shared), strings.Join(dirs, ", "))
	}

	topics := make([]Topic, 0, len(byTopic))
	for _, t := range byTopic {
		topics = append(topics, t)
	}
	sort.Slice(topics, func(i, j int) bool {
		if topics[i].Pubsub != topics[j].Pubsub {
			return topics[i].Pubsub < topics[j].Pubsub
		}
		return topics[i].Name < topics[j].Name
	})

	fields := map[string]TopicKey{}
	for _, t := range topics {
		if prev, ok := fields[t.Field]; ok {
			return nil, fmt.Errorf("topics %q (pubsub %q) and %q (pubsub %q) both map to field %s in Topics.cs; rename one topic", prev.Name, prev.Pubsub, t.Name, t.Pubsub, t.Field)
		}
		fields[t.Field] = t.TopicKey
	}

	connectors := make([]Connector, 0, len(byConnector))
	for name := range byConnector {
		connectors = append(connectors, Connector{Name: name, Field: pascalIdent(name)})
	}
	sort.Slice(connectors, func(i, j int) bool { return connectors[i].Name < connectors[j].Name })
	connectorFields := map[string]string{}
	for _, c := range connectors {
		if prev, ok := connectorFields[c.Field]; ok {
			return nil, fmt.Errorf("connectors %q and %q both map to field %s in Connectors.cs; rename one in the record's values", prev, c.Name, c.Field)
		}
		connectorFields[c.Field] = c.Name
	}

	return &Model{Components: components, Topics: topics, Connectors: connectors, Shared: shared[0]}, nil
}

// stringValue returns values[key] as a non-empty string, with errors that
// name the record so the user knows which project to fix.
func stringValue(e template.ScaffoldEntry, key string) (string, error) {
	record := filepath.Join(e.Path, filepath.FromSlash(template.ScaffoldRelPath))
	v, ok := e.Values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", record, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", record, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", record, key)
	}
	return s, nil
}

// stringValueDefault is stringValue with a fallback for records that
// predate the value being recorded.
func stringValueDefault(e template.ScaffoldEntry, key, fallback string) (string, error) {
	if _, ok := e.Values[key]; !ok {
		return fallback, nil
	}
	return stringValue(e, key)
}

// pascalIdent converts a DNS-ish name to a C# identifier: segments split
// on '-', '.' and '_' are title-cased and joined ("order-events" →
// "OrderEvents").
func pascalIdent(s string) string {
	segments := strings.FieldsFunc(s, func(r rune) bool {
		return r == '-' || r == '.' || r == '_'
	})
	var b strings.Builder
	for _, seg := range segments {
		b.WriteString(strings.ToUpper(seg[:1]))
		b.WriteString(seg[1:])
	}
	return b.String()
}

package system

// TopicKey identifies a topic within the system: the pub/sub component it
// lives on plus the topic name. Two scaffolds naming the same key declare
// the two halves of one contract.
type TopicKey struct {
	Pubsub string `json:"pubsub"`
	Name   string `json:"topic"`
}

// Topic is one assembled topic: its key, the C# contract type its messages
// carry, and the identifier it gets in the generated Topics class.
type Topic struct {
	TopicKey
	Contract string `json:"contract"`
	Field    string `json:"-"`
}

// Component is one assembled system block.
type Component struct {
	AppID     string   `json:"name"` // the AddExtractor/AddLoader argument
	Kind      string   `json:"kind"` // template.BlockKindExtractor or BlockKindLoader
	Topic     TopicKey `json:"-"`
	Connector string   `json:"connector,omitempty"` // the From/To port; empty for records that predate it
	Path      string   `json:"path"`                // scaffold directory, for error messages
}

// Connector is one assembled connector: the named port an edge block reaches
// the outside world through, and the identifier it gets in the generated
// Connectors class. The declaration carries only the deployed transport
// shape; `sys create` resolves every connector to a folder under the host's
// test/ directory through the generated development definition.
type Connector struct {
	Name  string `json:"name"`
	Field string `json:"-"`
}

// SharedLibrary is the workspace's contract project: referenced by the
// host, never declared as a component.
type SharedLibrary struct {
	Path string // scaffold directory
	Name string // project name; also the namespace and csproj basename
}

// Model is the assembled system declaration `sys create` generates code
// from. Name, ProjectName and SystemClass are filled in around the
// template render; Assemble leaves them empty.
type Model struct {
	Name        string // kebab-case system name
	ProjectName string // template-derived PascalCase name
	SystemClass string // template-derived ISystemDefinition class name
	Components  []Component
	Topics      []Topic     // sorted by (Pubsub, Name)
	Connectors  []Connector // sorted by Name
	Shared      SharedLibrary
}

package template

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

type CreateOptions struct {
	Template   string // required; subdirectory in the templates repo holding template.yaml + skeleton/
	OutputDir  string
	Version    string
	SetValues  map[string]any
	Files      []string
	Force      bool
	NoInput    bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdin      io.Reader
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Owner and Repo select the template library. Zero values target the
	// official library at integrio-intropy/intropy-templates; the CLI sets
	// them from --template-repo, INTROPY_TEMPLATE_REPO, or templateRepo in
	// the config file. GitHubBaseURL remains a test-only seam.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// CreateResult is the machine-readable summary written when --output-json is
// set. It is the contract chained scaffolder steps consume; field names are
// stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`

	// Dependencies reports what happened to each spec.dependencies entry
	// (including transitive ones): rendered now ("created") or already
	// present ("exists").
	Dependencies []DependencyResult `json:"dependencies,omitempty"`
}

func (o *CreateOptions) applyDefaults() {
	if o.Owner == "" {
		o.Owner = defaultTemplateOwner
	}
	if o.Repo == "" {
		o.Repo = defaultTemplateRepo
	}
	if o.Stdin == nil {
		o.Stdin = os.Stdin
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Create runs the full scaffold: resolve release, download tarball, extract,
// load manifest, resolve values (with optional interactive prompting), render.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if err := validateCreateOptions(opts); err != nil {
		return err
	}

	gh := newConfiguredGitHub(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
	tag, err := resolveReleaseTag(ctx, gh, opts.Owner, opts.Repo, opts.Version)
	if err != nil {
		return err
	}
	fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", opts.Owner, opts.Repo, tag)

	templateRoot, cleanup, err := downloadTemplate(ctx, gh, opts.Owner, opts.Repo, tag, opts.Template, "intropy-template-*")
	if err != nil {
		return err
	}
	defer cleanup()

	tmpl, values, err := prepareCreateTemplate(templateRoot, opts)
	if err != nil {
		return err
	}

	if err := renderCreateOutput(templateRoot, opts.Template, opts.OutputDir, opts.Force, values); err != nil {
		return err
	}
	fmt.Fprintf(opts.Stderr, "created %s from %s/%s@%s (template %s)\n", opts.OutputDir, opts.Owner, opts.Repo, tag, opts.Template)

	// Dependencies come from the same extracted tarball, so they are always
	// version-locked to the component that declared them.
	depRecords, depResults, err := processDependencies(tmpl, values, opts.OutputDir, &depContext{
		repoRoot: filepath.Dir(templateRoot),
		owner:    opts.Owner,
		repo:     opts.Repo,
		version:  tag,
		stderr:   opts.Stderr,
		visited:  map[string]bool{},
	}, 0)
	if err != nil {
		return err
	}

	// The template field is the repo directory name (opts.Template), not
	// tmpl.Metadata.Name — it is what a later re-fetch needs.
	if err := WriteScaffold(opts.OutputDir, Scaffold{
		SchemaVersion: ScaffoldSchemaVersion,
		Template:      opts.Template,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		Version:       tag,
		Values:        values,
		Role:          roleFromLabels(tmpl.Metadata.Labels),
		BlockKind:     blockKindFromLabels(tmpl.Metadata.Labels),
		DataFlow:      dataFlowFromLabels(tmpl.Metadata.Labels),
		DependsOn:     depRecords,
	}); err != nil {
		return err
	}

	return maybeWriteCreateResult(opts, tmpl, values, tag, depResults)
}

func validateCreateOptions(opts CreateOptions) error {
	if err := validateTemplateName(opts.Template); err != nil {
		return err
	}
	if opts.OutputDir == "" {
		return errors.New("--out-dir is required")
	}
	return nil
}

func prepareCreateTemplate(templateRoot string, opts CreateOptions) (*Template, map[string]any, error) {
	tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
	if err != nil {
		return nil, nil, err
	}

	prompter := selectPrompter(&opts)
	values, err := Resolve(tmpl, opts.Files, opts.Stdin, opts.SetValues, prompter)
	if err != nil {
		return nil, nil, err
	}
	return tmpl, values, nil
}

func renderCreateOutput(templateRoot, templateName, outputDir string, force bool, values map[string]any) error {
	skelRoot := filepath.Join(templateRoot, templateSkeletonDir)
	if info, err := os.Stat(skelRoot); err != nil || !info.IsDir() {
		return fmt.Errorf("template %q is missing %s/ directory", templateName, templateSkeletonDir)
	}
	if err := ensureOutputDir(outputDir, force); err != nil {
		return err
	}
	return Render(skelRoot, outputDir, values)
}

func maybeWriteCreateResult(opts CreateOptions, tmpl *Template, values map[string]any, tag string, deps []DependencyResult) error {
	if opts.OutputJSON == "" {
		return nil
	}

	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:     tmpl.Metadata.Name,
		Owner:        opts.Owner,
		Repo:         opts.Repo,
		Version:      tag,
		OutputDir:    absOut,
		Values:       values,
		Dependencies: deps,
	}
	if err := writeOutputJSON(opts.OutputJSON, opts.Stdout, result); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

func writeOutputJSON(path string, stdout io.Writer, r CreateResult) error {
	data, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	if path == "-" {
		_, err := stdout.Write(data)
		return err
	}
	return os.WriteFile(path, data, 0o644)
}

// EnsureOutputDir creates dir if missing and refuses to render into a
// non-empty directory unless force is set.
func EnsureOutputDir(dir string, force bool) error {
	return ensureOutputDir(dir, force)
}

func ensureOutputDir(dir string, force bool) error {
	info, err := os.Stat(dir)
	switch {
	case errors.Is(err, os.ErrNotExist):
		return os.MkdirAll(dir, 0o755)
	case err != nil:
		return err
	case !info.IsDir():
		return fmt.Errorf("--output %s exists and is not a directory", dir)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	if len(entries) > 0 && !force {
		return fmt.Errorf("--output %s is not empty (use --force to overwrite)", dir)
	}
	return nil
}

// validateTemplateName rejects empty names and anything that could escape the
// extracted tarball root via filepath.Join (separators, parent refs, hidden
// directories). The template argument is user input that we turn directly into
// a path segment, so it has to be sanitized.
func validateTemplateName(name string) error {
	if name == "" {
		return errors.New("template name is required")
	}
	if name == "." || name == ".." || strings.HasPrefix(name, ".") {
		return fmt.Errorf("invalid template name %q", name)
	}
	if strings.ContainsAny(name, `/\`) {
		return fmt.Errorf("invalid template name %q (must be a single path segment)", name)
	}
	return nil
}

func selectPrompter(opts *CreateOptions) Prompter {
	return AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
}

// AutoPrompter returns a StdinPrompter when interactive prompting is viable:
// noInput is false and stdin is a real terminal. In CI / piped contexts it
// returns nil, so Resolve reports a clean "missing required parameter(s)"
// error instead of hanging on a read.
func AutoPrompter(stdin io.Reader, out io.Writer, noInput bool) Prompter {
	if noInput {
		return nil
	}
	f, ok := stdin.(*os.File)
	if !ok || !isTerminal(f.Fd()) {
		return nil
	}
	return NewStdinPrompter(stdin, out)
}

package template

import (
	"fmt"
	"os"

	"gopkg.in/yaml.v3"
)

const (
	APIVersionV1 = "intropy.dev/v1"
	KindTemplate = "Template"
)

// Template is the on-disk manifest for a template. The envelope mirrors the
// Kubernetes / Backstage shape so authors recognize it at a glance; the body
// is a deliberately narrow subset (no ui: extensions, no step pipeline).
type Template struct {
	APIVersion string   `yaml:"apiVersion"`
	Kind       string   `yaml:"kind"`
	Metadata   Metadata `yaml:"metadata"`
	Spec       Spec     `yaml:"spec"`
}

type Metadata struct {
	Name        string            `yaml:"name"`
	Title       string            `yaml:"title,omitempty"`
	Description string            `yaml:"description,omitempty"`
	Tags        []string          `yaml:"tags,omitempty"`
	Labels      map[string]string `yaml:"labels,omitempty"`
}

type Spec struct {
	Parameters   map[string]any    `yaml:"parameters"`
	Values       map[string]string `yaml:"values,omitempty"`
	Files        []FileRule        `yaml:"files,omitempty"`
	Dependencies []DependencySpec  `yaml:"dependencies,omitempty"`

	// parameterOrder captures the declaration order of properties in
	// spec.parameters.properties, since Go maps don't preserve YAML order.
	// Populated by UnmarshalYAML.
	parameterOrder []string
}

// FileRule conditionally includes part of a skeleton, so one template can serve
// platforms whose manifest sets differ rather than only whose values differ.
//
// Path is a slash-separated glob relative to skeleton/, matched against the
// *source* path with any .tmpl suffix included — a rule that decides on values
// cannot depend on a path those values produce, so a templated directory segment
// is only reachable via a glob. A trailing "/**" also matches everything beneath
// the directory, and prunes it before its contents are parsed.
//
// When is a Go template (sprig available) rendered against the resolved values.
// Any result other than "", "false" or "0" includes the match.
//
// The first rule whose Path matches decides, and a path no rule matches is
// included — so a template without spec.files renders exactly as it did before
// this field existed.
type FileRule struct {
	Path string `yaml:"path" json:"path"`
	When string `yaml:"when" json:"when"`
}

// DependencySpec declares another template in the same library that must
// exist as a sibling of this template's output. Create renders it when the
// target directory is missing and skips it when a scaffold record from the
// same template is already there, so a shared project is created exactly
// once no matter how many components declare it.
type DependencySpec struct {
	// Template is the dependency's directory name in the templates repo.
	Template string `yaml:"template" json:"template"`
	// Output is a Go template (with sprig) rendered against the parent's
	// resolved values. It must produce a single path segment; the dependency
	// is created as a sibling of the parent's output directory.
	Output string `yaml:"output" json:"output"`
	// Values maps dependency parameter names to Go templates rendered
	// against the parent's resolved values. Dependencies resolve without
	// prompting, so together with the dependency's own defaults these must
	// cover every required parameter.
	Values map[string]string `yaml:"values,omitempty" json:"values,omitempty"`
}

// UnmarshalYAML decodes the spec and captures property declaration order
// so Fields() can return FieldSpecs in author-intended sequence.
func (s *Spec) UnmarshalYAML(node *yaml.Node) error {
	// Every field of Spec must be repeated here: the decode targets rawSpec, so
	// a field added to Spec alone is silently dropped.
	type rawSpec struct {
		Parameters   map[string]any    `yaml:"parameters"`
		Values       map[string]string `yaml:"values,omitempty"`
		Files        []FileRule        `yaml:"files,omitempty"`
		Dependencies []DependencySpec  `yaml:"dependencies,omitempty"`
	}
	var r rawSpec
	if err := node.Decode(&r); err != nil {
		return err
	}
	s.Parameters = r.Parameters
	s.Values = r.Values
	s.Files = r.Files
	s.Dependencies = r.Dependencies
	s.parameterOrder = extractPropertyOrder(node)
	return nil
}

func extractPropertyOrder(specNode *yaml.Node) []string {
	if specNode.Kind != yaml.MappingNode {
		return nil
	}
	paramsNode := childByKey(specNode, "parameters")
	if paramsNode == nil {
		return nil
	}
	propsNode := childByKey(paramsNode, "properties")
	if propsNode == nil || propsNode.Kind != yaml.MappingNode {
		return nil
	}
	order := make([]string, 0, len(propsNode.Content)/2)
	for i := 0; i < len(propsNode.Content); i += 2 {
		order = append(order, propsNode.Content[i].Value)
	}
	return order
}

func childByKey(mapping *yaml.Node, key string) *yaml.Node {
	if mapping.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i < len(mapping.Content); i += 2 {
		if mapping.Content[i].Value == key {
			return mapping.Content[i+1]
		}
	}
	return nil
}

// FieldSpec is the prompter/CLI view of a single property in spec.parameters.
// Prompters and form code only consume FieldSpecs — they never touch the raw
// JSON Schema map.
type FieldSpec struct {
	Name        string
	Title       string
	Description string
	Type        string // "string" | "boolean" | "integer" | "number"
	Enum        []any
	Default     any
	Pattern     string
	Required    bool
}

// Fields returns the JSON Schema properties as FieldSpecs in YAML declaration
// order.
func (t *Template) Fields() []FieldSpec {
	props, _ := t.Spec.Parameters["properties"].(map[string]any)
	if props == nil {
		return nil
	}
	required := map[string]bool{}
	if list, ok := t.Spec.Parameters["required"].([]any); ok {
		for _, r := range list {
			if s, ok := r.(string); ok {
				required[s] = true
			}
		}
	}
	out := make([]FieldSpec, 0, len(t.Spec.parameterOrder))
	for _, name := range t.Spec.parameterOrder {
		raw, _ := props[name].(map[string]any)
		out = append(out, fieldFromSchema(name, raw, required[name]))
	}
	return out
}

func fieldFromSchema(name string, schema map[string]any, required bool) FieldSpec {
	f := FieldSpec{Name: name, Required: required}
	if schema == nil {
		return f
	}
	f.Type, _ = schema["type"].(string)
	f.Title, _ = schema["title"].(string)
	f.Description, _ = schema["description"].(string)
	f.Pattern, _ = schema["pattern"].(string)
	f.Default = schema["default"]
	if e, ok := schema["enum"].([]any); ok {
		f.Enum = e
	}
	return f
}

// LoadTemplate reads and validates a template.yaml file.
func LoadTemplate(path string) (*Template, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read template: %w", err)
	}
	var t Template
	if err := yaml.Unmarshal(data, &t); err != nil {
		return nil, fmt.Errorf("parse template: %w", err)
	}
	if err := t.validate(); err != nil {
		return nil, fmt.Errorf("invalid template: %w", err)
	}
	return &t, nil
}

func (t *Template) validate() error {
	if t.APIVersion != APIVersionV1 {
		return fmt.Errorf("unsupported apiVersion %q (want %q)", t.APIVersion, APIVersionV1)
	}
	if t.Kind != KindTemplate {
		return fmt.Errorf("unsupported kind %q (want %q)", t.Kind, KindTemplate)
	}
	if t.Metadata.Name == "" {
		return fmt.Errorf("metadata.name is required")
	}
	if t.Spec.Parameters == nil {
		return fmt.Errorf("spec.parameters is required")
	}
	if typ, _ := t.Spec.Parameters["type"].(string); typ != "object" {
		return fmt.Errorf(`spec.parameters.type must be "object"`)
	}
	for i, rule := range t.Spec.Files {
		if rule.Path == "" {
			return fmt.Errorf("spec.files[%d]: path is required", i)
		}
		// A rule with no condition either does nothing or means the author
		// forgot the condition; neither deserves to render.
		if rule.When == "" {
			return fmt.Errorf("spec.files[%d] (%s): when is required", i, rule.Path)
		}
		// Parsed here so a syntax error surfaces at load time rather than
		// partway through a render.
		if _, err := compileExpr(rule.When); err != nil {
			return fmt.Errorf("spec.files[%d] (%s): invalid when: %w", i, rule.Path, err)
		}
	}
	for i, dep := range t.Spec.Dependencies {
		if err := validateTemplateName(dep.Template); err != nil {
			return fmt.Errorf("spec.dependencies[%d]: %w", i, err)
		}
		if dep.Output == "" {
			return fmt.Errorf("spec.dependencies[%d] (%s): output is required", i, dep.Template)
		}
	}
	return nil
}

package main

import (
	"os"
	"os/signal"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/system"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/spf13/cobra"
)

// sys create assembles scaffolded integrations into a system host. The
// scan, render, and assembly live in internal/system.Create; this file is
// flag plumbing.
type sysCreateFlags struct {
	name            string
	outDir          string
	output          string
	templateVersion string
	templateRepo    string
	force           bool
}

var sysCreateFlagValues sysCreateFlags

var sysCreateCmd = &cobra.Command{
	Use:   "create",
	Short: "Assemble scaffolded integrations into a system host",
	Long: "Scan the workspace for integration scaffold records (" + template.ScaffoldRelPath + "), render the system-host template, " +
		"and assemble the typed system declaration — Topics.cs and the ISystemDefinition class — from what the scaffolds recorded. " +
		"Run it from the workspace root that contains the scaffolded components and the shared contracts project.",
	Args: cobra.NoArgs,
	RunE: func(cmd *cobra.Command, args []string) error {
		if sysCreateFlagValues.output != "" && sysCreateFlagValues.output != "json" {
			return newUsageErrorf("invalid output format %q (allowed: json)", sysCreateFlagValues.output)
		}
		outputJSON := ""
		if sysCreateFlagValues.output == "json" {
			outputJSON = "-"
		}
		owner, repo, err := resolveTemplateRepo(sysCreateFlagValues.templateRepo)
		if err != nil {
			return err
		}
		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()
		return system.Create(ctx, system.CreateOptions{
			Name:       sysCreateFlagValues.name,
			OutputDir:  sysCreateFlagValues.outDir,
			Version:    sysCreateFlagValues.templateVersion,
			Force:      sysCreateFlagValues.force,
			OutputJSON: outputJSON,
			Stdout:     cmd.OutOrStdout(),
			Stderr:     cmd.ErrOrStderr(),
			UserAgent:  "intropy-cli/" + version,
			Owner:      owner,
			Repo:       repo,
		})
	},
}

func init() {
	f := sysCreateCmd.Flags()
	f.StringVarP(&sysCreateFlagValues.name, "name", "n", "", "system name; PascalCase or kebab-case (OrderFlow and order-flow are equivalent)")
	f.StringVarP(&sysCreateFlagValues.outDir, "out-dir", "o", "", "destination directory (default: the kebab-cased name)")
	f.StringVar(&sysCreateFlagValues.output, "output", "", flagUsageOutputJSONOnly)
	_ = sysCreateCmd.MarkFlagDirname("out-dir")
	f.StringVar(&sysCreateFlagValues.templateVersion, "template-version", "", flagUsageTemplateVer)
	f.StringVar(&sysCreateFlagValues.templateRepo, "template-repo", "", flagUsageTemplateRepo)
	f.BoolVar(&sysCreateFlagValues.force, "force", false, "allow rendering into a non-empty output directory")
	_ = sysCreateCmd.MarkFlagRequired("name")
	sysCmd.AddCommand(sysCreateCmd)
}

