func TestScratchArraysOfObjectsSetValues(t *testing.T) {
	yamlManifest := `apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: scratch
spec:
  parameters:
    type: object
    required: [topics]
    properties:
      topics:
        type: array
        minItems: 1
        items:
          type: object
          required: [name]
          properties:
            name: {type: string}
            field: {type: string}
`
	var tmpl Template
	if err := unmarshalManifest([]byte(yamlManifest), &tmpl); err != nil {
		t.Fatal(err)
	}

	sets := map[string]any{
		"topics": []any{
			map[string]any{"name": "orders", "field": "Orders", "extra": "untouched"},
		},
		"undeclaredKey": "surprise",
	}
	values, err := Resolve(&tmpl, nil, nil, sets, nil)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	t.Logf("resolved values: %#v", values)

	dir := t.TempDir()
	skel := filepath.Join(dir, "skeleton")
	if err := os.MkdirAll(skel, 0o755); err != nil {
		t.Fatal(err)
	}
	content := "{{ range .topics }}{{ .name }}={{ .field }} extra={{ .extra }};{{ end }} undeclared={{ .undeclaredKey }}\n"
	if err := os.WriteFile(filepath.Join(skel, "out.txt.tmpl"), []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	out := filepath.Join(dir, "out")
	if err := os.MkdirAll(out, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := Render(skel, out, values); err != nil {
		t.Fatalf("Render: %v", err)
	}
	got, err := os.ReadFile(filepath.Join(out, "out.txt"))
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("rendered: %q", got)
	if !strings.Contains(string(got), "orders=Orders extra=untouched; undeclared=surprise") {
		t.Errorf("unexpected render: %q", got)
	}
}

